    #[test]
    fn saved_pockets_with_missing_wall_leads_are_recomputed() {
        let op = cam_model::Operation::Pocket(leaded_op(vec![]));
        let env = JobEnv {
            heights: Heights::new(5., 2., 0.),
            tools: &[],
            stock: None,
            spindle: cam_cldata::SpindleDir::Cw,
        };
        let token = CancelToken::new();
        let mut cache = crate::OperationCache::default();
        cache.compute(&op, &env, &token, StrategyResult::default);
        let mut saved = serde_json::to_value(&cache).unwrap();
        saved["entries"][0]["key"]
            .as_object_mut()
            .unwrap()
            .remove("pocket_lead_revision");
        let mut reopened: crate::OperationCache = serde_json::from_value(saved).unwrap();
        reopened.compute(&op, &env, &token, StrategyResult::default);
        assert_eq!(reopened.stats.computed, 1);
        assert_eq!(reopened.stats.reused, 0);
        reopened.compute(&op, &env, &token, || {
            panic!("Current leads should be reused")
        });
        assert_eq!(reopened.stats.reused, 1);
    }

    #[test]
    fn single_ring_pocket_keeps_requested_wall_arc_leads() {
        for down in [false, true] {
            for start in [None, Some([5., 1.])] {
                for climb in [false, true] {
                    let mut op = leaded_op(vec![]);
                    // A 10 mm pocket and 8 mm cutter produce one wall ring. A
                    // small arc fits on its straight wall segments at both depths.
                    op.boundary = square(10.);
                    op.depth = 3.;
                    op.start = start;
                    op.clear.lead_in = Lead::Arc { radius: 0.25 };
                    op.clear.lead_out = Lead::Arc { radius: 0.25 };
                    op.clear.keep_tool_down = down;
                    op.clear.clearing.climb = climb;
                    let result = finishing_result(op);
                    assert!(!result.has_errors(), "{:?}", result.diagnostics);
                    result.program.validate().unwrap();
                    assert_eq!(
                        leadin_arcs(&result).len(),
                        4,
                        "down {down}, start {start:?}, climb {climb}: {:#?}",
                        result.program.steps()
                    );
                    let sim = cam_sim::simulate(
                        &result.program,
                        [-1., -1., -4.],
                        [11., 11., 0.],
                        &cam_sim::SimOptions {
                            resolution: 0.25,
                            tool_radius: 4.,
                        },
                        &[],
                    );
                    assert!(sim.is_clean(), "{:?}", sim.collisions);
                }
            }
        }
    }

    #[test]
    fn wall_leads_ease_onto_the_boundary_from_inside() {
        let ts = tools(8.0);
        let env = JobEnv {
            heights: Heights::new(5.0, 2.0, 0.0),
            tools: &ts,
            stock: None,
            spindle: cam_cldata::SpindleDir::Cw,
        };
        let result = PocketStrategy::new(leaded_op(vec![])).compute(&env, &CancelToken::new());
        assert!(!result.has_errors(), "{:?}", result.diagnostics);
        let arcs = leadin_arcs(&result);
        assert_eq!(
            arcs.len(),
            2,
            "one lead-in + one lead-out on the single boundary wall"
        );
        // The lead-in comes from the cleared interior: its entry is closer to the
        // pocket centre (20,20) than the wall point it eases onto.
        let (entry, wall) = arcs[0];
        let d = |p: Point| (p.x - 20.0).hypot(p.y - 20.0);
        assert!(
            d(entry) < d(wall),
            "lead-in must ease in from inside, entry {:?} wall {:?}",
            (entry.x, entry.y),
            (wall.x, wall.y)
        );

        // No leads emitted when unset.
        let mut plain = leaded_op(vec![]);
        plain.clear.lead_in = Lead::None;
        plain.clear.lead_out = Lead::None;
        let r2 = PocketStrategy::new(plain).compute(&env, &CancelToken::new());
        assert!(leadin_arcs(&r2).is_empty(), "no leads when unset");
    }

    /// Signed area of the ordered cutting-move endpoints (shoelace); its sign is the
    /// overall travel winding, which flips between climb and conventional.
    fn cutting_path_signed_area(result: &StrategyResult) -> f64 {
        let pts: Vec<(f64, f64)> = result
            .program
            .steps()
            .iter()
            .filter_map(|s| match s {
                Step::Linear { to, tag, .. } if tag.kind == MoveKind::Cutting => Some((to.x, to.y)),
                Step::Arc { end, tag, .. } if tag.kind == MoveKind::Cutting => Some((end.x, end.y)),
                _ => None,
            })
            .collect();
        let n = pts.len();
        (0..n)
            .map(|i| {
                let (ax, ay) = pts[i];
                let (bx, by) = pts[(i + 1) % n];
                ax * by - bx * ay
            })
            .sum()
    }

    #[test]
    fn engagement_cap_tightens_the_spacing() {
        // A 2 mm engagement cap on a ⌀8 tool forces 2 mm rings where 50% overlap
        // alone would space them 4 mm — so more rings, more cutting moves.
        let run = |engagement: f64| {
            let mut op = leaded_op(vec![]);
            op.clear.lead_in = Lead::None;
            op.clear.lead_out = Lead::None;
            op.clear.clearing = Clearing {
                engagement,
                climb: true,
            };
            let ts = tools(8.0);
            let env = JobEnv {
                heights: Heights::new(5.0, 2.0, 0.0),
                tools: &ts,
                stock: None,
                spindle: cam_cldata::SpindleDir::Cw,
            };
            let r = PocketStrategy::new(op).compute(&env, &CancelToken::new());
            assert!(!r.has_errors(), "{:?}", r.diagnostics);
            cutting_moves(&r)
        };
        assert!(
            run(2.0) > run(0.0),
            "a tighter engagement cap ⇒ more rings ({} vs {})",
            run(2.0),
            run(0.0)
        );
    }

    #[test]
    fn an_engagement_capped_climb_pocket_ships_the_certified_front_advance_path() {
        // The end-to-end proof that wiring front-advance into `clearing::clear` emits a
        // *bounded* toolpath — not just that the generator does. A 40×40 pocket, ⌀6 tool
        // (r=3), engagement 2.0, climb, no leads, one depth level: this satisfies every
        // dispatch guard, so `clear` routes through `front_advance_certified` and
        // `emit_adaptive`. We rebuild the tool-centre polyline from the *emitted* moves
        // (the plunge landing = path start, then the cutting moves) and re-certify it
        // against the exact oracle. Concentric would slot this pocket at ~6.0 (the full
        // ⌀6 diameter) at the entry and the pass-to-pass links; front-advance holds it at
        // the geometric floor. The gate is 1.5·e = 3.0 — see
        // `frontadvance::CERT_ENGAGEMENT_SLACK`.
        let op = PocketOp {
            maximum_stepover: None,
            parameter_expressions: Default::default(),
            wrap: None,
            additional_regions: Vec::new(),
            stock_contours: Default::default(),
            finishing: Default::default(),
            spindle_rpm: 0.0,
            tool_preset: None,
            cooling: Default::default(),
            entry_feeds: Default::default(),
            work_offset: 1,
            id: 0,
            tool: 1,
            boundary: square(40.0),
            islands: vec![],
            depth: 2.0,
            end: None,
            start: None,
            clear: ClearParams {
                multiple_depths: Default::default(),
                adaptive_enabled: None,
                pocket_overlap: None,
                keep_tool_down: false,
                lift_height: 0.0,
                clearing: Clearing {
                    engagement: 2.0,
                    climb: true,
                },
                // one depth level
                stepdown: 2.0,
                overlap: 0.5,
                offset: 0.0,
                feed: 300.0,
                plunge_feed: 100.0,
                plunge: Plunge::Straight,
                lead_overlap: 0.0,
                lead_in: Lead::None,
                lead_out: Lead::None,
            },
        };
        let ts = tools(6.0);
        let env = JobEnv {
            heights: Heights::new(5.0, 2.0, 0.0),
            tools: &ts,
            stock: None,
            spindle: cam_cldata::SpindleDir::Cw,
        };
        let result = PocketStrategy::new(op).compute(&env, &CancelToken::new());
        assert!(!result.has_errors(), "{:?}", result.diagnostics);

        // Reconstruct the first level's tool-centre path: the plunge lands at the path
        // start, then every cutting move is a path vertex. Stop at the first retract.
        let mut path: Vec<Point> = Vec::new();
        for s in result.program.steps() {
            match s {
                Step::Linear { to, tag, .. } if tag.kind == MoveKind::Plunge => {
                    if path.is_empty() {
                        path.push(Point::new(to.x, to.y));
                    }
                }
                Step::Linear { to, tag, .. } if tag.kind == MoveKind::Cutting => {
                    path.push(Point::new(to.x, to.y));
                }
                Step::Rapid { tag, .. } if tag.kind == MoveKind::Retract => break,
                _ => {}
            }
        }
        assert!(
            path.len() > 50,
            "a front-advance spiral is many small moves, got {}",
            path.len()
        );

        // Certify the *shipped* path against the exact oracle. finish=0 ⇒ the material to
        // clear is the boundary itself.
        let region = Polygon::new(square(40.0)).expect("square is a valid polygon");
        let verdict = crate::clearsim::certify(&path, 3.0, &region);
        assert!(
            verdict.max_engagement <= 2.0 * 1.5 + 1e-6,
            "the emitted path must hold engagement at the certified bound (1.5·e = 3.0), \
             got {:.2}",
            verdict.max_engagement
        );
        // And it is unmistakably the front-advance path, not a slotting fallback: a
        // concentric clear of this pocket slots at ~6.0 (the full diameter) at entry.
        assert!(
            verdict.max_engagement < 4.0,
            "engagement {:.2} is nowhere near a slot (~6.0) — the front-advance path shipped",
            verdict.max_engagement
        );
    }

    #[test]
    fn conventional_milling_reverses_travel_but_keeps_leads_inside() {
        let ts = tools(8.0);
        let env = JobEnv {
            heights: Heights::new(5.0, 2.0, 0.0),
            tools: &ts,
            stock: None,
            spindle: cam_cldata::SpindleDir::Cw,
        };
        // Same pocket, climb vs conventional: the overall travel winding flips sign.
        let climb = {
            let mut op = leaded_op(vec![]);
            op.clear.lead_in = Lead::None;
            op.clear.lead_out = Lead::None;
            op.clear.clearing = Clearing {
                engagement: 0.0,
                climb: true,
            };
            PocketStrategy::new(op).compute(&env, &CancelToken::new())
        };
        let conv = {
            let mut op = leaded_op(vec![]);
            op.clear.lead_in = Lead::None;
            op.clear.lead_out = Lead::None;
            op.clear.clearing = Clearing {
                engagement: 0.0,
                climb: false,
            };
            PocketStrategy::new(op).compute(&env, &CancelToken::new())
        };
        let a_climb = cutting_path_signed_area(&climb);
        let a_conv = cutting_path_signed_area(&conv);
        assert!(
            a_climb * a_conv < 0.0,
            "conventional must reverse travel: signed areas {a_climb} vs {a_conv}"
        );

        // With conventional milling *and* wall leads, the lead must still ease in from
        // the cleared interior (not swing onto the wall) — the reversal is threaded
        // through to the lead's cleared-side normal.
        let mut leaded = leaded_op(vec![]);
        leaded.clear.clearing = Clearing {
            engagement: 0.0,
            climb: false,
        };
        let r = PocketStrategy::new(leaded).compute(&env, &CancelToken::new());
        assert!(!r.has_errors(), "{:?}", r.diagnostics);
        let arcs = leadin_arcs(&r);
        assert_eq!(arcs.len(), 2, "conventional still leads on/off the wall");
        let d = |p: Point| (p.x - 20.0).hypot(p.y - 20.0);
        let (entry, wall) = arcs[0];
        assert!(
            d(entry) < d(wall),
            "conventional lead must still come from inside: entry {:?} wall {:?}",
            (entry.x, entry.y),
            (wall.x, wall.y)
        );
    }

    #[test]
    fn a_lead_too_big_for_the_pocket_is_dropped_not_overshot() {
        // A 10×10 pocket with a ⌀6 tool clears to a 4×4 wall ring — only 2 mm of
        // room from that wall to the centre. A radius-3 arc lead cannot fit without
        // swinging past the far wall, so it must be dropped to a plain pass (no lead
        // arc), never emitted overshooting the boundary. High overlap gives the
        // multiple rings that put the wall ring on the leaded path in the first place.
        let small = PocketOp {
            maximum_stepover: None,
            parameter_expressions: Default::default(),
            wrap: None,
            additional_regions: Vec::new(),
            stock_contours: Default::default(),
            finishing: Default::default(),
            spindle_rpm: 0.0,
            tool_preset: None,
            cooling: Default::default(),
            entry_feeds: Default::default(),
            work_offset: 1,
            id: 0,
            tool: 1,
            boundary: square(10.0),
            islands: vec![],
            depth: 1.5,
            end: None,
            start: None,
            clear: ClearParams {
                multiple_depths: Default::default(),
                adaptive_enabled: None,
                pocket_overlap: None,
                keep_tool_down: false,
                lift_height: 0.0,
                clearing: cam_model::Clearing::default(),
                stepdown: 1.5,
                overlap: 0.9,
                offset: 0.0,
                feed: 300.0,
                plunge_feed: 100.0,
                plunge: Plunge::Straight,
                lead_overlap: 0.0,
                lead_in: Lead::Arc { radius: 3.0 },
                lead_out: Lead::Arc { radius: 3.0 },
            },
        };
        let ts = tools(6.0);
        let env = JobEnv {
            heights: Heights::new(5.0, 2.0, 0.0),
            tools: &ts,
            stock: None,
            spindle: cam_cldata::SpindleDir::Cw,
        };
        let result = PocketStrategy::new(small).compute(&env, &CancelToken::new());
        assert!(!result.has_errors(), "{:?}", result.diagnostics);
        assert!(
            leadin_arcs(&result).is_empty(),
            "an oversized lead must be dropped, not emitted past the wall: {:?}",
            leadin_arcs(&result)
        );

        // Every emitted cut stays inside the pocket boundary [0,10]² (no overshoot).
        for s in result.program.steps() {
            let p = match s {
                Step::Linear { to, tag, .. } if tag.kind == MoveKind::Cutting => Some((to.x, to.y)),
                Step::Arc { end, tag, .. } if tag.kind == MoveKind::Cutting => Some((end.x, end.y)),
                _ => None,
            };
            if let Some((x, y)) = p {
                assert!(
                    (-1e-6..=10.0 + 1e-6).contains(&x) && (-1e-6..=10.0 + 1e-6).contains(&y),
                    "cut left the pocket at ({x}, {y})"
                );
            }
        }
    }

    #[test]
    fn wall_leads_reach_islands_without_gouging() {
        // A centred 8×8 island: both the boundary and the island wall get leads,
        // and no lead cuts into the island material [16,24] (verifies the lead sits
        // on the pocket side of the island, i.e. the winding is read correctly).
        let island = Contour::new(vec![
            Point::new(16.0, 16.0),
            Point::new(24.0, 16.0),
            Point::new(24.0, 24.0),
            Point::new(16.0, 24.0),
        ]);
        let ts = tools(6.0);
        let env = JobEnv {
            heights: Heights::new(5.0, 2.0, 0.0),
            tools: &ts,
            stock: None,
            spindle: cam_cldata::SpindleDir::Cw,
        };
        let result =
            PocketStrategy::new(leaded_op(vec![island])).compute(&env, &CancelToken::new());
        assert!(!result.has_errors(), "{:?}", result.diagnostics);
        let arcs = leadin_arcs(&result);
        assert_eq!(
            arcs.len(),
            4,
            "leads on the boundary and the island (2 each)"
        );
        for (entry, _) in &arcs {
            let into_island = entry.x > 16.0 && entry.x < 24.0 && entry.y > 16.0 && entry.y < 24.0;
            assert!(
                !into_island,
                "a lead cut into the island, entry ({}, {})",
                entry.x, entry.y
            );
        }
    }
